import { styled } from "@stitches/react";

export const MainWrapper = styled("div", {
  border: "2px solid blue",
  height: "100vh",
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  flexDirection: "column",
  width: '100%'
});

export const ContentWrapper = styled("div", {
  border: "2px solid blue",
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  width: '100%',
  padding: '3rem'
});
